"""Curated field guide. Images and their full provenance live in challenge-sources.json."""
import json
from pathlib import Path

root = Path(__file__).resolve().parent.parent
path = root / 'src/data/locations.json'
existing = json.loads(path.read_text(encoding='utf-8'))[:6]
for w in existing:
    w['category'] = 'planets' if w['id'] in ('mars', 'venus') else 'exotic' if w['id'] == 'blackhole' else 'moons'
    w['viewType'] = 'panorama'
    w['preview'] = f"/objects/{w['id']}.svg"
    w['texture'] = f"/textures/{w['id']}.svg"
    w['scale'] = w['distance']
    w['characteristic'] = w['temperature']
    w['feature'] = w['gravity']

# id, name, type, color, clues (progressively more specific), explanation, fact
