sources = json.loads((root / 'challenge-sources.json').read_text(encoding='utf-8'))
for category, entries in rows.items():
    for key, name, kind, color, clues, explanation, fact in entries:
        source = sources[f'public/challenges/{key}.jpg']
        illustration = key in ('white-dwarf', 'red-dwarf')
        existing.append(dict(id=key, name=name, type=kind, color=color, category=category, tagline=fact,
            image=f'/challenges/{key}.jpg', preview=f'/objects/{key}.svg', texture=f'/textures/{key}.svg',
            imageType='NASA artist illustration' if illustration else 'NASA archive image', viewType='photo',
            credit=source['credit'], source=source['source'], clues=clues, explanation=explanation, fact=fact,
            note=f"{source['title']}. {source['processing']}",
            distance='See field notes', temperature='Varies', gravity='Varies',
            scale=kind.split(' · ')[0], characteristic='Illustration' if illustration else 'Spacecraft / telescope', feature=category.replace('-', ' ').title()))
path.write_text(json.dumps(existing, indent=2, ensure_ascii=False) + '\n', encoding='utf-8')
print(f'{len(existing)} destinations across seven categories.')
